import React, { useMemo, useState, useEffect } from 'react';
import { Loader2, Clock } from 'lucide-react';

interface CardCanvasProps {
  memberId: string;
  memberName: string;
  imageUrl?: string;
  referenceTimestamp?: number;
}

const CardCanvas: React.FC<CardCanvasProps> = ({ memberId, memberName, imageUrl, referenceTimestamp }) => {
  const [imageState, setImageState] = useState<'loading' | 'success' | 'error'>('loading');
  const [currentCandidateIndex, setCurrentCandidateIndex] = useState(0);

  // --- LOGO PEÑA ---
  const PENA_LOGO_ID = "17pNVMd42F6pDU7LOCPjPZ-xrUckcYNMe";
  // Usamos Thumbnail API + Proxy para máxima compatibilidad CORS
  const WM_SRC = `https://wsrv.nl/?url=${encodeURIComponent(`https://drive.google.com/thumbnail?id=${PENA_LOGO_ID}&sz=w1000`)}&output=png`;

  // --- EXPIRATION LOGIC ---
  const expirationString = useMemo(() => {
    const date = referenceTimestamp ? new Date(referenceTimestamp) : new Date();
    date.setHours(date.getHours() + 96);
    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    return `${day}/${month}`;
  }, [referenceTimestamp]);

  // --- IMAGE SOURCE STRATEGY ---
  const imageCandidates = useMemo(() => {
    if (!imageUrl) return [];

    // Extraer ID de Drive
    const driveIdMatch = imageUrl.match(/\/d\/([^/]+)|id=([^&]+)/);
    const driveId = driveIdMatch ? (driveIdMatch[1] || driveIdMatch[2]) : null;

    // Si no es de Drive, pasamos por proxy simple
    if (!driveId) {
        return [
            `https://wsrv.nl/?url=${encodeURIComponent(imageUrl)}&w=1000&output=jpg`,
            imageUrl
        ];
    }

    // ESTRATEGIA DEFINITIVA PARA DRIVE:
    // 1. Base: Usar la API de 'thumbnail' (sz=w1200) en lugar de 'export=view'.
    //    Motivo: 'export=view' tiene redirects y rate-limits que rompen los proxies. 'thumbnail' es directa.
    // 2. Proxy: Pasamos esa URL base por wsrv.nl para obtener cabeceras CORS limpias.

    const googleThumbUrl = `https://drive.google.com/thumbnail?id=${driveId}&sz=w1200`;

    return [
        // OPCIÓN A: Proxy sobre Thumbnail (La más rápida y segura para CORS)
        `https://wsrv.nl/?url=${encodeURIComponent(googleThumbUrl)}&output=jpg`,

        // OPCIÓN B: Directo a Thumbnail (Fallback si wsrv cae)
        googleThumbUrl
    ];
  }, [imageUrl]);

  const currentSrc = imageCandidates[currentCandidateIndex];

  useEffect(() => {
    if (imageUrl) {
        setImageState('loading');
        setCurrentCandidateIndex(0);
    } else {
        setImageState('error');
    }
  }, [imageUrl]);

  const handleImageError = () => {
    if (currentCandidateIndex < imageCandidates.length - 1) {
        // Si falla el proxy, probamos directo
        setCurrentCandidateIndex(prev => prev + 1);
    } else {
        setImageState('error');
    }
  };

  const handleImageLoad = () => {
      setImageState('success');
  };

  // --- SVG FALLBACK ---
  const svgFallbackUrl = useMemo(() => {
    const width = 600; const height = 900; 
    const svgString = `
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}">
        <defs><linearGradient id="grad1" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" style="stop-color:#004899;stop-opacity:1"/><stop offset="100%" style="stop-color:#002a5c;stop-opacity:1"/></linearGradient></defs>
        <rect width="100%" height="100%" fill="url(#grad1)"/>
        <text x="300" y="300" text-anchor="middle" font-family="Arial" font-weight="bold" font-size="34" fill="white">Imagen no disponible</text>
        <text x="300" y="350" text-anchor="middle" font-family="Arial" font-size="24" fill="white" opacity="0.7">Pase Digital de Respaldo</text>
      </svg>`;
    return `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svgString)))}`;
  }, []);

  return (
    <div id={`card-${memberId}`} className="relative w-full max-w-[340px] mx-auto bg-white">

      {/* CARD CONTAINER */}
      <div className="relative overflow-hidden rounded-[24px] shadow-[0_20px_50px_rgba(0,0,0,0.5)] bg-white flex flex-col min-h-[200px]">

        {/* 1. IMAGE AREA */}
        <div className="relative w-full bg-gray-100">

            {/* Loading Overlay */}
            {imageState === 'loading' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-50 z-20 min-h-[400px]">
                    <Loader2 className="w-8 h-8 animate-spin text-depor-blue mb-2" />
                </div>
            )}

            {/* MAIN IMAGE */}
            {currentSrc && (
                <img 
                    src={currentSrc}
                    alt="Abono"
                    crossOrigin="anonymous"
                    // IMPORTANTE: Eliminada la clase 'transition-opacity' y 'duration-300'.
                    // Las transiciones CSS causan que html-to-image capture la imagen a media opacidad (blanca).
                    className={`w-full h-auto block ${imageState === 'success' ? 'opacity-100' : 'opacity-0'}`}
                    onLoad={handleImageLoad}
                    onError={handleImageError}
                />
            )}

            {/* Fallback */}
            {imageState === 'error' && (
                <img src={svgFallbackUrl} alt="Error" className="w-full h-auto object-cover relative z-10" />
            )}

            {/* 2. DATA OVERLAY */}
            <div className="absolute top-0 left-0 w-full pt-6 pb-12 px-5 bg-gradient-to-b from-black/60 via-black/20 to-transparent z-30 pointer-events-none">
                 <div className="flex flex-col items-start w-full drop-shadow-md">
                    <h2 className="text-2xl font-black text-white leading-tight uppercase tracking-tight" style={{ textShadow: '0 2px 4px rgba(0,0,0,0.8)' }}>
                        {memberName}
                    </h2>
                    <div className="mt-2 w-full flex items-center justify-between">
                        <span className="bg-white/20 backdrop-blur-md text-white text-[11px] font-bold px-2 py-0.5 rounded border border-white/30 shadow-sm">
                            ID: {memberId}
                        </span>
                        <span className="flex items-center gap-1 bg-orange-600/90 backdrop-blur-md text-white text-[10px] font-bold px-2 py-0.5 rounded border border-white/20 shadow-sm">
                            <Clock className="w-3 h-3" />
                            CADUCA: {expirationString}
                        </span>
                    </div>
                 </div>
            </div>

            {/* 3. WATERMARK */}
            <div className="absolute top-[15%] left-0 w-full h-[40%] flex items-center justify-center pointer-events-none z-20 overflow-hidden">
                <img 
                    src={WM_SRC} 
                    alt="" 
                    crossOrigin="anonymous"
                    className="w-[40%] opacity-25 grayscale contrast-150 brightness-95 mix-blend-multiply"
                />
            </div>

            {/* Scanline */}
            <div className="absolute top-0 w-full h-[1px] bg-white/30 shadow-[0_0_10px_rgba(255,255,255,0.4)] animate-[scan_4s_linear_infinite] pointer-events-none z-30"></div>
        </div>

        {/* Hologram Overlay */}
        <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent opacity-20 pointer-events-none z-40" style={{ mixBlendMode: 'overlay' }}></div>
      </div>

      <p className="text-center text-[10px] text-gray-400 mt-4 font-medium uppercase tracking-widest">
        Aumente el brillo de la pantalla al máximo
      </p>
    </div>
  );
};

