const SecureViewer: React.FC = () => {
  const [member, setMember] = useState<Member | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');
  const [referenceTimestamp, setReferenceTimestamp] = useState<number | undefined>(undefined);
  const [forcedImageUrl, setForcedImageUrl] = useState<string | undefined>(undefined);
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
        const hash = window.location.hash;
        const queryString = hash.split('?')[1];
        const urlParams = new URLSearchParams(queryString);
        const id = urlParams.get('id');
        const timestampStr = urlParams.get('t'); const slotIdStr = urlParams.get('slot');
        if (!id) { setError('Enlace inválido.'); setLoading(false); return; }
        if (timestampStr) { const timestamp = parseInt(timestampStr); setReferenceTimestamp(timestamp); if (Date.now() > timestamp + (96 * 60 * 60 * 1000)) { setIsExpired(true); setLoading(false); return; } }
        if (slotIdStr) { const slotConfig = PASS_SLOTS.find(s => s.slotId === parseInt(slotIdStr)); if (slotConfig) setForcedImageUrl(slotConfig.imageUrl); }
        try { const members = await fetchMembers(); const found = members.find(m => m.id === id); if (found) setMember(found); else setError('Socio no encontrado.'); } catch (e) { setError('Error de conexión.'); } finally { setLoading(false); }
    };
    fetchData();
  }, []);

  if (loading) return <div className="min-h-screen flex items-center justify-center bg-neutral-900 text-white">Cargando...</div>;
  if (isExpired) return <div className="min-h-screen flex flex-col items-center justify-center bg-neutral-900 text-white text-center p-4"><AlertTriangle className="w-16 h-16 text-red-500 mb-4"/><h1>Enlace Caducado</h1></div>;
  if (error || !member) return <div className="min-h-screen flex items-center justify-center bg-neutral-900 text-white">{error}</div>;

  return <div className="min-h-screen bg-neutral-900 flex flex-col items-center justify-center secure-view"><CardCanvas memberId={member.id} memberName={member.name} imageUrl={forcedImageUrl || member.imageUrl} referenceTimestamp={referenceTimestamp} /></div>;
};

const App: React.FC = () => {
  const [route, setRoute] = useState<'dashboard' | 'view'>('dashboard');
  useEffect(() => { const handleRoute = () => setRoute(window.location.hash.includes('/view') ? 'view' : 'dashboard'); handleRoute(); window.addEventListener('hashchange', handleRoute); return () => window.removeEventListener('hashchange', handleRoute); }, []);
  return <>{route === 'dashboard' ? <Dashboard /> : <SecureViewer />}</>;
};

