                          const isAssigned = (Object.values(assignments) as Member[]).some(m => m.id === member.id && assignments[currentSlotId!]?.id !== member.id);
                          return <button key={member.id} onClick={() => !isAssigned && handleAssignMember(member)} disabled={isAssigned} className={`w-full text-left p-3 rounded-xl border flex justify-between ${isAssigned ? 'opacity-50 bg-gray-50' : 'bg-white hover:bg-blue-50'}`}><div><p className="font-bold text-sm">{member.name}</p><span className="text-xs text-gray-400">ID: {member.id}</span></div>{isAssigned && <span className="text-[10px] bg-gray-200 px-2 py-1 rounded">Ocupado</span>}</button>;
                      })}
                  </div>
              </div>
          </div>
      )}

      {(quickShareData || selectedPreviewData) && (
        <div className="fixed inset-0 bg-neutral-900/60 backdrop-blur-sm z-50 flex flex-col items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-3xl p-6 shadow-2xl relative">
                <button onClick={() => {closeQuickShare(); closePreview();}} className="absolute right-4 top-4 text-gray-400"><XCircle className="w-6 h-6" /></button>
                <div id={`popup-card`} className="mb-4 flex justify-center"><CardCanvas memberId={(quickShareData || selectedPreviewData)!.member.id} memberName={(quickShareData || selectedPreviewData)!.member.name} imageUrl={(quickShareData || selectedPreviewData)!.imageUrl} referenceTimestamp={lastResetTime} /></div>
                {/* Eliminado el botón "Descargar Imagen" */}
                {quickShareData && (<div className="grid grid-cols-2 gap-3"><a href={getWhatsAppMessage(quickShareData.member, generateLinkForMember(quickShareData.member, lastResetTime, quickShareData.slotId))} target="_blank" rel="noreferrer" className="bg-[#25D366] text-white font-bold py-3 px-4 rounded-xl text-center text-sm flex items-center justify-center gap-2 hover:bg-[#20bd5a] transition-all"><Send className="w-4 h-4" /> WhatsApp</a><button onClick={() => handleCopyLink(quickShareData.member, quickShareData.slotId)} className="bg-blue-50 text-depor-blue border border-blue-100 font-bold py-3 px-4 rounded-xl text-sm flex items-center justify-center gap-2 hover:bg-blue-100 transition-all"><Link className="w-4 h-4" /> Copiar Enlace</button></div>)}
             </div>
        </div>
      )}
    </div>
  );
};

// --- SecureViewer ---
const SecureViewer: React.FC = () => {
  const [member, setMember] = useState<Member | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');
  const [referenceTimestamp, setReferenceTimestamp] = useState<number | undefined>(undefined);
  const [forcedImageUrl, setForcedImageUrl] = useState<string | undefined>(undefined);
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
        const hash = window.location.hash;
        const queryString = hash.split('?')[1];
        const urlParams = new URLSearchParams(queryString);
        const id = urlParams.get('id');
        const timestampStr = urlParams.get('t'); const slotIdStr = urlParams.get('slot');
        if (!id) { setError('Enlace inválido.'); setLoading(false); return; }
        if (timestampStr) { const timestamp = parseInt(timestampStr); setReferenceTimestamp(timestamp); if (Date.now() > timestamp + (96 * 60 * 60 * 1000)) { setIsExpired(true); setLoading(false); return; } }
        if (slotIdStr) { const slotConfig = PASS_SLOTS.find(s => s.slotId === parseInt(slotIdStr)); if (slotConfig) setForcedImageUrl(slotConfig.imageUrl); }
        try { const members = await fetchMembers(); const found = members.find(m => m.id === id); if (found) setMember(found); else setError('Socio no encontrado.'); } catch (e) { setError('Error de conexión.'); } finally { setLoading(false); }
    };
    fetchData();
  }, []);

  if (loading) return <div className="min-h-screen flex items-center justify-center bg-neutral-900 text-white">Cargando...</div>;
  if (isExpired) return <div className="min-h-screen flex flex-col items-center justify-center bg-neutral-900 text-white text-center p-4"><AlertTriangle className="w-16 h-16 text-red-500 mb-4"/><h1>Enlace Caducado</h1></div>;
  if (error || !member) return <div className="min-h-screen flex items-center justify-center bg-neutral-900 text-white">{error}</div>;

  return <div className="min-h-screen bg-neutral-900 flex flex-col items-center justify-center secure-view"><CardCanvas memberId={member.id} memberName={member.name} imageUrl={forcedImageUrl || member.imageUrl} referenceTimestamp={referenceTimestamp} /></div>;
};

