      try {
          // Simplificado al máximo para velocidad:
          // 1. Sin cacheBust (usa la caché del navegador para la imagen de fondo)
          // 2. Sin fetchRequestInit complejo
          await new Promise(r => setTimeout(r, 50)); // Breve pausa para UI update

          const blob = await toBlob(node, { 
              pixelRatio: 2, 
              backgroundColor: '#ffffff'
          });

          if (!blob) throw new Error("Blob generado vacío");

          try { 
              await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]); 
              alert("📋 ¡Imagen del sorteo copiada!"); 
          } catch (e) { 
              const link = document.createElement('a'); 
              link.download = `Sorteo_${matchName}.png`; 
              link.href = URL.createObjectURL(blob); 
              link.click(); 
          }
      } catch (e) { 
          console.error(e); 
          alert("No se pudo copiar la imagen.");
      } finally {
          setIsProcessingRaffleImage(false);
          document.body.style.cursor = 'default';
      }
  };

