                                                    <a href={getWhatsAppMessage(member, generateLinkForMember(member, lastResetTime, slot.slotId))} target="_blank" rel="noreferrer" className="p-2 text-green-600 hover:bg-green-50 rounded-full transition-colors" title="WhatsApp">
                                                        <MessageCircle size={18} />
