// --- Viewer Component (Standalone) ---
const Viewer: React.FC = () => {
    const [member, setMember] = useState<Member | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [slotInfo, setSlotInfo] = useState<{imageUrl: string, seatInfo: string} | null>(null);

    useEffect(() => {
        const loadData = async () => {
            try {
                // Parse Hash Params manually because URLSearchParams might not handle hash correctly in all browsers
                const hashPart = window.location.hash.split('?')[1];
                const params = new URLSearchParams(hashPart);

                const id = params.get('id');
                const slotIdStr = params.get('slot');

                if (!id) throw new Error("Enlace incompleto");

                // Get Member Data
                const members = await fetchMembers();
                const foundMember = members.find(m => m.id === id);

                if (!foundMember) throw new Error("Socio no encontrado");
                setMember(foundMember);

                // Get Slot Data
                if (slotIdStr) {
                    const foundSlot = PASS_SLOTS.find(s => s.slotId.toString() === slotIdStr);
                    if (foundSlot) {
                        setSlotInfo({ imageUrl: foundSlot.imageUrl, seatInfo: foundSlot.seatInfo });
                    }
                }

                // If no specific slot image, use default fallback
                if (!slotInfo && !slotIdStr) {
                     setSlotInfo({ imageUrl: DEFAULT_IMAGES[0], seatInfo: '' });
                }

            } catch (err: any) {
                setError(err.message || "Error cargando el abono");
            } finally {
                setLoading(false);
            }
        };
        loadData();
    }, []);

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center text-white">
                <Loader2 className="w-10 h-10 animate-spin text-blue-500 mb-4" />
                <p className="font-medium animate-pulse">Verificando acceso...</p>
            </div>
        );
    }

    if (error || !member) {
        return (
            <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-6 text-center">
                <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center mb-4">
                    <XCircle className="w-8 h-8 text-red-500" />
                </div>
                <h2 className="text-white text-xl font-bold mb-2">Acceso Denegado</h2>
                <p className="text-gray-400">{error}</p>
            </div>
        );
    }

    const params = new URLSearchParams(window.location.hash.split('?')[1]);
    const timestamp = parseInt(params.get('t') || '0');

    return (
        <div className="min-h-screen bg-black flex items-center justify-center p-4">
             <CardCanvas 
                memberId={member.id}
                memberName={member.name}
                imageUrl={slotInfo?.imageUrl || DEFAULT_IMAGES[0]}
                referenceTimestamp={timestamp > 0 ? timestamp : Date.now()}
                seatInfo={slotInfo?.seatInfo}
             />
        </div>
    );
};

// --- Main App Entry Point ---
const App: React.FC = () => {
    // Simple Hash Router to switch between Admin Dashboard and Public Viewer
    const [currentRoute, setCurrentRoute] = useState(window.location.hash);

    useEffect(() => {
        const onHashChange = () => setCurrentRoute(window.location.hash);
        window.addEventListener('hashchange', onHashChange);
        return () => window.removeEventListener('hashchange', onHashChange);
    }, []);

    // Check if route starts with #/view
    if (currentRoute.includes('#/view')) {
        return <Viewer />;
    }

    return <Dashboard />;
};

