export const fetchMembers = async (): Promise<Member[]> => {
  try {
    const response = await fetch(`${CSV_URL}&t=${Date.now()}`);
    if (!response.ok) {
      throw new Error(`Error fetching sheet: ${response.statusText}`);
    }
    const text = await response.text();
    const rawData = parseCSV(text);

    return rawData.map((row, index) => {
        const keys = Object.keys(row);

        const findKey = (searchTerms: string[]) => {
            for (const term of searchTerms) {
                const found = keys.find(k => k.toLowerCase().includes(term.toLowerCase()));
                if (found) return found;
            }
            return '';
        };

        let imgKey = findKey(['imagen', 'foto', 'photo', 'img']);
        let rawImgUrl = imgKey ? row[imgKey] : '';

        if (!rawImgUrl && index < DEFAULT_IMAGES.length) {
            rawImgUrl = DEFAULT_IMAGES[index];
        } else if (!rawImgUrl) {
             rawImgUrl = DEFAULT_IMAGES[index % DEFAULT_IMAGES.length];
        }

        // 1. PRIORIDAD: Columna "2025" para el estado de pago
        const paymentKey = findKey(['2025', '25/26', 'cuota', 'pagad', 'pago']);
        const rawPaidValue = paymentKey ? row[paymentKey] : 'NO';
        const cleanPaid = rawPaidValue.replace(/["']/g, '').trim().toUpperCase();

        const positiveValues = ['SI', 'SÍ', 'S', 'YES', 'Y', 'TRUE', 'T', '1', 'OK', 'PAGADO', 'ACTIVO'];
        const isPaid = positiveValues.some(val => cleanPaid === val || cleanPaid.startsWith(val));

        // 2. HISTORIAL: Extraer solo si hay partidos ganados reales (Columna E y F)
        const historySet = new Set<string>();

        // Revisamos las columnas 4 y 5 (E y F en Excel) que suelen ser Ganador/Partido
        const colE = keys[4] ? row[keys[4]]?.trim().toUpperCase() : '';
        const colF = keys[5] ? row[keys[5]]?.trim() : '';

        if (colE && (colE.includes('GANADOR') || colE === 'SI' || colE === 'SÍ')) {
            if (colF && colF.toUpperCase() !== 'NO' && colF !== '-') {
                historySet.add(colF); // Añadimos el nombre del partido ganado
            }
        }

        return {
            id: row[findKey(['id', 'socio', 'número', 'numero'])] || '0',
            name: row[findKey(['nombre', 'name', 'apellidos'])] || 'Desconocido',
            phone: row[findKey(['teléfono', 'telefono', 'movil', 'phone', 'tfn'])] || '',
            paid: isPaid ? 'SI' : 'NO',
            imageUrl: rawImgUrl,
            history: Array.from(historySet),
            ...row
        };
    });
  } catch (error) {
    console.error("Failed to load members", error);
    return [];
  }
};

