  const raffleStats = useMemo(() => {
      // Socios que han pagado la cuota 2025
      const activeMembers = allMembers.filter(m => m.paid === 'SI');

      // Socios que PUEDEN entrar en el bombo:
      // - Tienen pagada la cuota ('SI')
      // - NO han ganado en el ciclo actual de la aplicación
      // - NO tienen historial de victorias previas importadas del Excel
      const pendingToWin = activeMembers.filter(m => {
          const hasWonInCurrentCycle = cycleHistory.includes(m.id);
          const hasExternalHistory = m.history && m.history.length > 0;
          return !hasWonInCurrentCycle && !hasExternalHistory;
      });

      return { 
          total: allMembers.length, 
          active: activeMembers.length, 
          pending: pendingToWin.length
