];

export const fetchMembers = async (): Promise<Member[]> => {
  try {
    const response = await fetch(`${CSV_URL}&t=${Date.now()}`);
    if (!response.ok) {
      throw new Error(`Error fetching sheet: ${response.statusText}`);
    }
    const text = await response.text();

    // Usamos una versión modificada de parseado para obtener arrays de strings y evitar errores de nombres de cabecera
    const lines = text.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) return [];

    // Parseo manual robusto para manejar comas dentro de comillas
    const parseLine = (line: string) => {
      const result = [];
      let cur = '';
      let inQuote = false;
      for (let i = 0; i < line.length; i++) {
        const char = line[i];
        if (char === '"') inQuote = !inQuote;
        else if (char === ',' && !inQuote) {
          result.push(cur.trim());
          cur = '';
        } else cur += char;
      }
      result.push(cur.trim());
      return result;
    };

    const dataRows = lines.slice(1).map(line => parseLine(line));

    return dataRows.map((row, index) => {
      // Mapeo según especificación:
      // A (0): ID
      // B (1): Nombre Socio
      // C (2): Teléfono
      // D (3): Cuota Pagada (SI o NO)
      // E (4): Socio Ganador (SI/NO/Partido)
      // F (5): Partido Ganador

      const id = row[0] || `S-${index}`;
      const name = row[1] || 'Socio Desconocido';
      const phone = row[2] || '';

      // Columna D: Pago
      const rawPaid = (row[3] || '').toUpperCase();
      const isPaid = rawPaid === 'SI' || rawPaid === 'SÍ' || rawPaid === 'OK';

      const historySet = new Set<string>();

      // Columna E y F: Historial
      const colE = (row[4] || '').toUpperCase();
      const colF = (row[5] || '').trim();

      // Si en la columna E pone SI, SÍ o el nombre de un partido, es que ya ha ganado
      if (colE === 'SI' || colE === 'SÍ' || (colE.length > 2 && colE !== 'NO')) {
        // Priorizamos el nombre del partido de la columna F, si no, el de la E
        const matchName = colF && colF.toUpperCase() !== 'NO' ? colF : (colE !== 'SI' && colE !== 'SÍ' ? row[4] : 'Partido Anterior');
        if (matchName) historySet.add(matchName);
      }

      // Imagen por defecto o desde columna G (si existe)
      let imageUrl = row[6] || DEFAULT_IMAGES[index % DEFAULT_IMAGES.length];
      if (!imageUrl.startsWith('http')) {
        imageUrl = DEFAULT_IMAGES[index % DEFAULT_IMAGES.length];
      }

      return {
        id,
        name,
        phone,
        paid: isPaid ? 'SI' : 'NO',
        imageUrl,
        history: Array.from(historySet)
      };
    });
  } catch (error) {
    console.error("Failed to load members", error);
    return [];
  }
};

