      const activeMembers = allMembers.filter(m => m.paid === 'SI');

      // 3. Pendientes: Pagados que NO han ganado (Ni en Excel ni en App Cycle)
      const pendingToWin = activeMembers.filter(m => {
          const wonInApp = cycleHistory.includes(m.id);
          const wonInExcel = m.history && m.history.length > 0;
          return !wonInApp && !wonInExcel;
