];

export const fetchMembers = async (): Promise<Member[]> => {
  try {
    const response = await fetch(`${CSV_URL}&t=${Date.now()}`);
    if (!response.ok) {
      throw new Error(`Error fetching sheet: ${response.statusText}`);
    }
    const text = await response.text();

    // Parseo manual línea a línea para asegurar el orden de las columnas A a F
    const lines = text.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) return [];

    const parseLine = (line: string) => {
      const result = [];
      let cur = '';
      let inQuote = false;
      for (let i = 0; i < line.length; i++) {
        const char = line[i];
        if (char === '"') inQuote = !inQuote;
        else if (char === ',' && !inQuote) {
          result.push(cur.trim());
          cur = '';
        } else cur += char;
      }
      result.push(cur.trim());
      return result;
    };

    // Obtenemos los datos ignorando la cabecera
    const dataRows = lines.slice(1).map(line => parseLine(line));

    return dataRows.map((row, index) => {
        // Estructura solicitada:
        // A (0): ID
        // B (1): Nombre Socio
        // C (2): Teléfono (Sin +34)
        // D (3): Cuota Pagada (SI o NO)
        // E (4): Socio Ganador en jornadas anteriores
        // F (5): Partido Ganador

        const id = row[0]?.replace(/^"|"$/g, '') || `S-${index}`;
        const name = row[1]?.replace(/^"|"$/g, '') || 'Socio Desconocido';
        const phone = row[2]?.replace(/^"|"$/g, '') || '';

        // Columna D: Pago
        const rawPaidValue = (row[3] || '').replace(/^"|"$/g, '').trim().toUpperCase();
        const isPaid = rawPaidValue === 'SI' || rawPaidValue === 'SÍ' || rawPaidValue === 'OK';

        // Historial (Columnas E y F)
        const historySet = new Set<string>();
        const colE = (row[4] || '').replace(/^"|"$/g, '').trim().toUpperCase();
        const colF = (row[5] || '').replace(/^"|"$/g, '').trim();

        // Si la columna E indica que ha ganado (contiene SI o un nombre de partido)
        // O si la columna F tiene un nombre de partido
        if (colE === 'SI' || colE === 'SÍ' || (colE !== 'NO' && colE !== '' && colE !== '-')) {
            const partido = (colF && colF.toUpperCase() !== 'NO' && colF !== '-') ? colF : (colE !== 'SI' && colE !== 'SÍ' ? row[4] : 'Jornada Anterior');
            if (partido) historySet.add(partido);
        }

        // Imagen: Si hay columna G (6) la usamos, si no, fallback
        let imageUrl = row[6] ? row[6].replace(/^"|"$/g, '') : '';
        if (!imageUrl || !imageUrl.startsWith('http')) {
            imageUrl = DEFAULT_IMAGES[index % DEFAULT_IMAGES.length];
        }

        return {
            id,
            name,
            phone,
            paid: isPaid ? 'SI' : 'NO',
            imageUrl,
            history: Array.from(historySet)
        };
    });
  } catch (error) {
    console.error("Failed to load members", error);
    return [];
  }
};

