      try {
          setAssignments({}); const now = Date.now(); setLastResetTime(now);
          const data = await fetchMembers(); setAllMembers(data);
          await persistState({ assignments: {}, lastResetTime: now });
      } catch (e) { console.error(e); } finally { setLoading(false); }
  };

