const SecureViewer: React.FC = () => {
  const [member, setMember] = useState<Member | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');
  const [referenceTimestamp, setReferenceTimestamp] = useState<number | undefined>(undefined);
  const [forcedImageUrl, setForcedImageUrl] = useState<string | undefined>(undefined);
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
        const hash = window.location.hash;
        const queryString = hash.split('?')[1];
        const urlParams = new URLSearchParams(queryString);
        const id = urlParams.get('id');
        const tStr = urlParams.get('t'); 
        const slotStr = urlParams.get('slot');

        if (!id) { setError('Inválido'); setLoading(false); return; }
        if (tStr) { 
            const t = parseInt(tStr); 
            setReferenceTimestamp(t); 
            if (Date.now() > t + (96 * 60 * 60 * 1000)) { setIsExpired(true); setLoading(false); return; } 
        }
        if (slotStr) { 
            const slot = PASS_SLOTS.find(s => s.slotId === parseInt(slotStr)); 
            if (slot) setForcedImageUrl(slot.imageUrl);
        }

        try { 
            const members = await fetchMembers(); 
            const found = members.find(m => m.id === id); 
            if (found) setMember(found); else setError('No encontrado'); 
        } catch (e) { setError('Error de red'); } finally { setLoading(false); }
    };
    fetchData();
  }, []);

  if (loading) return <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white flex-col"><Loader2 className="w-8 h-8 animate-spin mb-4 text-blue-500"/><p>Verificando...</p></div>;
  if (isExpired) return <div className="min-h-screen flex flex-col items-center justify-center bg-gray-900 text-white p-4"><h1>Caducado</h1></div>;
  if (error || !member) return <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white">{error}</div>;

  return (
    <div className="min-h-screen bg-black flex flex-col items-center justify-center secure-view p-4">
        <CardCanvas memberId={member.id} memberName={member.name} imageUrl={forcedImageUrl || member.imageUrl} referenceTimestamp={referenceTimestamp} />
    </div>
  );
};

const App: React.FC = () => {
  const [route, setRoute] = useState<'dashboard' | 'view'>('dashboard');
  useEffect(() => { 
    const handleRoute = () => setRoute(window.location.hash.includes('/view') ? 'view' : 'dashboard'); 
    handleRoute(); window.addEventListener('hashchange', handleRoute); 
    return () => window.removeEventListener('hashchange', handleRoute); 
  }, []);
  return <>{route === 'dashboard' ? <Dashboard /> : <SecureViewer />}</>;
};

